    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "not enough balance");

        uint256 beforePastBlockTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        (bool sent, ) = address(c).call{value: amount}("");
        reverted = !sent;

        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp);
            assert(block.timestamp > beforePastBlockTime);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == amount);
            } else {
                assert(address(c).balance == beforeBalance + amount);
                assert(address(this).balance == 0);
            }
        } else {
            assert(c.pastBlockTime() == beforePastBlockTime);
            assert(address(c).balance == beforeBalance);
            assert(address(this).balance == amount);
            assert(block.timestamp <= beforePastBlockTime);
        }
    }

    receive() external payable {}
}

