contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint64 newTime, uint amount) public payable {
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "not enough balance");

        uint oldTime = c.pastBlockTime();
        require(newTime > oldTime, "newTime not greater than oldTime");

        // Set the next block timestamp for the test environment.
        // This is the only way to make the contract's require(block.timestamp > pastBlockTime) pass deterministically.
        // In a property-based test on a live chain, the caller cannot control block.timestamp; here we
        // assume the test harness supports setting the next block timestamp via this special cheatcode-like mechanism.
        // However, the constraints forbid vm.* cheatcodes. Therefore, we instead make the precondition ensure
        // that the current block.timestamp is greater than oldTime.
        // If the current block.timestamp is not greater than oldTime, the call would revert, so we require it.
        require(block.timestamp > oldTime, "current block timestamp not greater than oldTime");

        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (block.number % 15 == 0) {
            // The contract transfers the entire balance to msg.sender (this contract).
            // The fallback should have succeeded and transferred the balance.
            assert(!reverted && address(c).balance == 0 && address(this).balance == balanceBefore + amount);
        } else {
            // The fallback should have succeeded and kept the balance.
            assert(!reverted && address(c).balance == balanceBefore + amount);
        }

        // Additionally, check that the timestamp was updated to the block timestamp at the time of the call.
        // We cannot know the exact block.timestamp after the call if the block number condition was true and the balance was transferred,
        // but the state variable should be updated regardless.
        assert(c.pastBlockTime() == block.timestamp);
    }

    receive() external payable {}
}

