contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint64 t, uint256 amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Ensure the timestamp is far enough in the future to pass the require.
        uint256 beforePastBlockTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        if (block.timestamp > beforePastBlockTime) {
            uint256 balBefore = address(this).balance;
            try c.call{value: amount}("") {
                // Call succeeded.
                reverted = false;

                // The test's balance must have decreased by exactly the sent amount.
                assert(address(this).balance == balBefore - amount);

                // pastBlockTime must have been updated to the current timestamp.
                assert(c.pastBlockTime() == block.timestamp);

                // The contract's balance behavior: if payout occurred (block.number % 15 == 0),
                // the contract's balance became 0; otherwise it increased by amount.
                if (block.number % 15 == 0) {
                    assert(address(c).balance == 0);
                } else {
                    assert(address(c).balance == beforeBalance + amount);
                }
            } catch {
                reverted = true;
                // A revert should not change pastBlockTime.
                assert(c.pastBlockTime() == beforePastBlockTime);
            }
        }

        // The general rule: the storage variable pastBlockTime is either unchanged (when reverting or precondition fails)
        // or set to the current timestamp (when the call succeeds).
        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            assert(c.pastBlockTime() == beforePastBlockTime);
        }
    }

    receive() external payable {}
}

