    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint blockNum = block.number;

        bool reverted;
        try address(c).call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted);
        assert(c.pastBlockTime() == block.timestamp);
        if (blockNum % 15 == 0) {
            assert(address(c).balance == 0);
        } else {
            assert(address(c).balance == balBefore + amount);
        }
    }

    receive() external payable {}
}

