contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint firstTimestamp, uint finalTimestamp) public payable {
        require(firstTimestamp > 0);
        require(finalTimestamp > firstTimestamp);
        require(address(this).balance >= 10 ether);

        uint previousBalance = address(this).balance;

        c.fallback{value: 10 ether}();
        // Cannot make block.timestamp > firstTimestamp in the test harness.
        // Use two identical fallback calls to expose the timestamp rule:
        c.fallback{value: 10 ether}();

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || address(this).balance >= previousBalance - 20 ether);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint firstTimestamp, uint finalTimestamp) public payable {
        // precondition: provide enough Ether for two potential 10 ether calls
        require(address(this).balance >= 20 ether);

        // first call: send exactly 10 ether; if it succeeds, pastBlockTime becomes the current block timestamp, else it remains 0.
        bool firstSucceeded;
        try c.{value: 10 ether}() {
            firstSucceeded = true;
        } catch {
            firstSucceeded = false;
        }

        uint recordedAfterFirst = c.pastBlockTime();

        // second call: send exactly 10 ether again; timestamp must increase if first succeeded and the conditions hold.
        bool secondSucceeded;
        try c.{value: 10 ether}() {
            secondSucceeded = true;
        } catch {
            secondSucceeded = false;
        }

        uint recordedAfterSecond = c.pastBlockTime();

        // General rule: a call that updates the timestamp must have a strictly greater timestamp than the previous recorded value.
        // Also, if the first call succeeded, any subsequent successful call must leave a higher timestamp than the first,
        // unless the block number is not divisible by 15 (in which case no balance transfer happens but timestamp still updates).
        if (secondSucceeded) {
            assert(recordedAfterSecond > recordedAfterFirst);
        } else {
            assert(recordedAfterSecond == recordedAfterFirst);
        }
    }

    receive() external payable {}
}

