contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        // Ensure the test contract can cover the attempted value transfer.
        require(address(this).balance >= amount);

        // Snapshot the observable state before the state-changing call.
        uint beforeTime = c.pastBlockTime();

        // Attempt the fallback call. The test contract makes the call, so
        // msg.sender for C will be address(this).
        bool ok;
        (ok, ) = address(c).call{value: amount}("");

        // Read the observable state after the call.
        uint afterTime = c.pastBlockTime();

        // General rule: the call succeeds exactly when the supplied value is
        // 10 ether and the block timestamp strictly increased during the call.
        // If it fails, pastBlockTime must be unchanged.
        assert(ok ? (amount == 10 ether && afterTime > beforeTime) : afterTime == beforeTime);
    }

    receive() external payable {}
}

