contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint timestamp, uint blockNumber) public payable {
        require(address(this).balance >= 10 ether);
        require(timestamp > c.pastBlockTime());

        // Set block.timestamp and block.number for the whole test transaction.
        require(uint256(blockhash(blockNumber)) == 0); // just to use blockNumber? no, use vm. Instead, skip.

        // Helper for setting block values without cheatcodes: use cast? Can't. So we must assume
        // the harness lets us set block.timestamp and block.number via parameters? No.
        // In a single call we cannot change block.timestamp/block.number, so we read them.
        // We use the current block's timestamp and number as observed.
        uint currentTimestamp = block.timestamp;
        uint currentBlockNumber = block.number;

        // To exercise both branches, we need a way to choose whether block.number % 15 == 0.
        // Since we cannot change block.number, we cannot force a branch change in one call.
        // But the property can be conditional on the observed block number.

        // We need pastBlockTime to be less than currentTimestamp for the call to succeed.
        // Since c.pastBlockTime() starts at 0, and block.timestamp is > 0, the precondition holds.

        uint beforeBalance = address(c).balance;

        // The deciding call: send exactly 10 ether to the fallback.
        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, read the new balance.
        uint afterBalance = address(c).balance;

        // General rule:
        // If the call did not revert, then either block.number % 15 != 0 and
        // the balance increased by exactly 10 ether, or block.number % 15 == 0 and
        // the balance became exactly 0 (all Ether was transferred to the caller).
        // Also, pastBlockTime must equal the timestamp of the call.
        assert(
            reverted ||
            (block.number % 15 != 0 && afterBalance == beforeBalance + 10 ether && address(this).balance >= 10 ether) ||
            (block.number % 15 == 0 && afterBalance == 0)
        );
    }

    receive() external payable {}
}

