        c.fallback{value: 10 ether}();

        uint256 before = c.pastBlockTime();
        require(before == block.timestamp);

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterVal = c.pastBlockTime();
        assert(reverted == (block.timestamp <= before) && (!reverted || afterVal == block.timestamp));
    }

    receive() external payable {}
